const now=new Date(),state={user:null,preview:[],previewCompany:null,companies:[],news:[],selected:'',date:dayKey(now),year:now.getFullYear(),month:now.getMonth(),busy:false,message:'',query:'',matches:[],summaryOpen:false,dayOpen:false,rankingPage:false,summaryBusy:false,summaryMessage:''};
