let podcastMentionDates=new Map();
let podcast={...podcastPreferences(),episodes:[],updated_at:'',error:'',loading:false};
async function loadPodcasts(refresh=false){if(podcast.loading)return;const owner=state.user?.id||null;podcast.loading=true;podcast.error='';render();try{const data=await fetchPodcastEpisodes({refresh,previousEpisodes:podcast.episodes,previousUpdatedAt:podcast.updated_at,shared:!!state.user});if(owner===(state.user?.id||null)){Object.assign(podcast,data);void acquirePodcastTranscripts(data.episodes,owner||'guest',{isCurrent:()=>owner===(state.user?.id||null)&&podcast.episodes===data.episodes,onUpdate:()=>render()}).then(()=>runPodcastAuto(data.episodes,owner,{isCurrent:()=>owner===(state.user?.id||null)}));}}catch(e){if(owner===(state.user?.id||null))podcast.error=e.message;}finally{podcast.loading=false;render();}}

let holdingsDetail=null;
function openHoldings(){holdingsDetail={records:loadHoldings(state.user.id),broker:'sinopac',unit:'share',text:'',quotes:{}};render();app.querySelector('#close-holdings')?.focus();refreshHoldingsQuotes();}
async function refreshHoldingsQuotes(){const detail=holdingsDetail,owner=state.user?.id;if(!detail)return;const rows=detail.records[detail.broker]?.rows||[];detail.quotes={};if(!rows.length){render();return;}detail.message='讀取已保存行情…';render();try{const data=await api('/portfolio-quotes?codes='+rows.map(r=>r.code).join(','));if(holdingsDetail===detail&&state.user?.id===owner){detail.quotes=Object.fromEntries(data.quotes.map(q=>[q.code,q]));detail.message=`取得 ${data.quotes.length} 檔已保存行情。`;}}catch(e){if(holdingsDetail===detail&&state.user?.id===owner)detail.error=e.message;}if(holdingsDetail===detail)render();}
let maSettings=readMASettings();
let chainCatalog=null,chainError='';let ranking=null,rankingTag='',rankingDate='',rankingError='',observationRequest=0,rankingDetail=null,rankingRequest=0;
async function openRankingStock(code){const request=++rankingRequest,owner=state.user?.id;rankingDetail={...maSettings,code,stock:ranking?.stocks.find(r=>r.code===code)||state.companies.find(c=>c.code===code)||state.previewCompany,loading:true};render();app.querySelector('#close-stock-ranking')?.focus();rankingDetail.profileLoading=true;readCompanyProfile(code).then(result=>{if(request===rankingRequest&&owner===state.user?.id){rankingDetail.profile=result.profile;rankingDetail.profileError=result.warning||'';}}).catch(e=>{if(request===rankingRequest&&owner===state.user?.id)rankingDetail.profileError=e.message;}).finally(()=>{if(request===rankingRequest&&owner===state.user?.id){rankingDetail.profileLoading=false;render();}});try{const [data,chart]=await Promise.all([api('/ranking-stock?code='+encodeURIComponent(code)),api('/chart-prices?code='+encodeURIComponent(code))]);if(request===rankingRequest&&owner===state.user?.id)Object.assign(rankingDetail,{...data,stock:data.stock||state.companies.find(c=>c.code===code)||rankingDetail.stock,code,prices:chart.prices,priceSource:chart.source,candlePeriod:'day',...maSettings,loading:false});}catch(e){if(request===rankingRequest&&owner===state.user?.id)Object.assign(rankingDetail,{loading:false,error:e.message});}if(request===rankingRequest){render();refreshLiveCandles();}}
async function toggleRankingNews(refresh=false){
 const detail=rankingDetail,owner=state.user?.id;if(!detail||detail.newsLoading)return;
 if(detail.newsOpen&&!refresh){detail.newsOpen=false;render();return;}
 detail.newsOpen=true;
 if(detail.recentNews&&!refresh){render();return;}
 detail.newsLoading=true;detail.newsError='';render();
 try{const result=await api('/preview?code='+encodeURIComponent(detail.code));if(rankingDetail===detail&&owner===state.user?.id)detail.recentNews=curateNews(result.news||[]).sort((a,b)=>String(b.published_at||b.news_date).localeCompare(String(a.published_at||a.news_date)));}
 catch(e){if(rankingDetail===detail&&owner===state.user?.id){detail.newsError=e.message||'新聞來源暫時無法讀取，請稍後重試';detail.recentNews??=state.news.filter(n=>n.company_code===detail.code);}}
 finally{if(rankingDetail===detail&&owner===state.user?.id){detail.newsLoading=false;render();}}
}
async function changeCandlePeriod(period,force=false){const detail=rankingDetail;if(!detail)return;detail.candlePeriod=period;if(!period.endsWith('m')){render();return;}if(detail.minuteData?.[period]&&!force){render();return;}detail.minuteLoading=true;detail.minuteError='';render();try{const result=await api(`/intraday?code=${detail.code}&interval=${period}${force?'&refresh=1':''}`);if(rankingDetail===detail){detail.minuteData??={};detail.minuteData[period]=result.prices;}}catch(e){if(rankingDetail===detail)detail.minuteError=e.message;}finally{if(rankingDetail===detail){detail.minuteLoading=false;render();}}}
async function refreshLiveCandles(){
 const detail=rankingDetail,owner=state.user?.id;
 if(!detail||!owner||detail.loading||detail.livePaused||detail.liveLoading||detail.minuteLoading||detail.candleRefreshing||document.hidden||!marketOpen())return;
 detail.liveLoading=true;
 const period=detail.candlePeriod||'day',interval=period.endsWith('m')?period:'1d';
 try{const result=await api(`/intraday?code=${detail.code}&interval=${interval}`);
  if(rankingDetail!==detail||state.user?.id!==owner||detail.candlePeriod!==period)return;
  if(interval==='1d')detail.prices=mergeLiveBars(detail.prices,result.prices);
  else {detail.minuteData??={};detail.minuteData[period]=result.prices;}
  detail.liveUpdated=new Date(result.updatedAt).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei'});
  detail.liveQuoteTime=result.prices.at(-1)?.date||'尚無資料';detail.liveError='';
 }catch(e){if(rankingDetail===detail)detail.liveError='盤中更新失敗，下一分鐘重試';}
 finally{detail.liveLoading=false;if(rankingDetail===detail)render();}
}
setInterval(refreshLiveCandles,60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLiveCandles();});
function closeRankingStock(){const code=rankingDetail?.code;rankingRequest++;rankingDetail=null;render();app.querySelector(`[data-stock="${code}"]`)?.focus();}
async function loadObservationTechnicals(data,request,owner){
 if(!chainCatalog||!data.date)return;
 const candidates=observationCandidates(tenDayTrends(turnoverFrames(chainCatalog,data.history,data.date)),data.stocks,state.companies);
 data.observationTechnicals={};data.observationLoading=!!candidates.length;render();
 for(let i=0;i<candidates.length;i+=4){
  if(request!==observationRequest||owner!==state.user?.id)return;
  const results=await Promise.allSettled(candidates.slice(i,i+4).map(async r=>{
   const result=await api('/chart-prices?code='+encodeURIComponent(r.code));
   return [r.code,observationTechnical(result.prices||[],data.date)];
  }));
  if(request!==observationRequest||owner!==state.user?.id)return;
  results.forEach((r,j)=>{const code=candidates[i+j].code;data.observationTechnicals[code]=r.status==='fulfilled'?r.value[1]:{eligible:false,reason:'行情讀取失敗，請重試'};});
 }
 data.observationLoading=false;if(ranking===data)render();
}
async function loadRankingReturns(data,request,owner){
 data.priceReturns={};data.priceReturnsLoading=true;render();
 const stocks=[...(data.stocks||[])].sort((a,b)=>b.amount-a.amount||a.code.localeCompare(b.code)).slice(0,10);
 await Promise.allSettled(stocks.map(async stock=>{
  try{const result=await api('/chart-prices?code='+encodeURIComponent(stock.code));if(ranking===data&&request===observationRequest&&owner===state.user?.id){data.priceReturns[stock.code]=rankingReturns(result.prices,data.date,data.dates);}}
  catch{if(ranking===data&&request===observationRequest&&owner===state.user?.id)data.priceReturns[stock.code]=rankingReturns([],data.date,data.dates);}
 }));
 if(ranking===data&&request===observationRequest&&owner===state.user?.id){data.priceReturnsLoading=false;render();}
}
async function loadRanking(date=''){
 const request=++observationRequest,owner=state.user?.id;
 try{
  if(!chainCatalog){try{const r=await fetch(import.meta.env.BASE_URL+'data/value-chains.json');if(!r.ok)throw Error('分類資料讀取失敗');chainCatalog=await r.json();chainError='';}catch(e){chainError=e.message;}}
  let data=await api('/ranking'+(date?'?date='+encodeURIComponent(date):''));
  if(data.date&&!data.previousStocks){const index=data.dates?.indexOf(data.date),previousDate=data.previousDate||data.dates?.[index+1];if(previousDate){try{const previous=await api('/ranking?date='+encodeURIComponent(previousDate));data={...data,previousDate:previous.date,previousStocks:previous.stocks};}catch{}}}
  if(request!==observationRequest||owner!==state.user?.id)return;
  ranking=data;rankingDate=data.date||'';rankingTag='';rankingError='';
  loadRankingReturns(data,request,owner);
  loadObservationTechnicals(data,request,owner).catch(()=>{if(ranking===data&&request===observationRequest){data.observationLoading=false;data.observationError='技術條件讀取失敗，請重新選擇交易日期重試';render();}});
 }catch(e){if(request===observationRequest)rankingError=e.message;}render();
}

let marketPrices={},priceMessage={};
const priceLoads=new Map();
async function loadPrices(code,{notify=true}={}){if(!code||!state.user||marketPrices[code])return;const owner=state.user.id;if(priceLoads.has(code))return priceLoads.get(code);const task=(async()=>{try{const result=await api('/prices?code='+encodeURIComponent(code));if(state.user?.id===owner){marketPrices[code]=result.prices;priceMessage[code]='';}}catch(e){if(state.user?.id===owner)priceMessage[code]=e.message;}finally{priceLoads.delete(code);if(notify&&state.user?.id===owner)render();}})();priceLoads.set(code,task);return task;}
let priceBackground=false;
async function loadBackgroundPrices(){if(priceBackground)return;priceBackground=true;const owner=state.user?.id;try{const codes=state.companies.filter(c=>!marketPrices[c.code]).map(c=>c.code);for(let i=0;i<codes.length;i+=4){if(state.user?.id!==owner)break;await Promise.all(codes.slice(i,i+4).map(code=>loadPrices(code,{notify:false})));}}finally{priceBackground=false;if(state.user?.id===owner)render();}}
let monthLoadVersion=0,calendarSwitchVersion=0;
async function switchCalendarMonth(year,month,date){const version=++calendarSwitchVersion,d=new Date(year,month,1);state.year=d.getFullYear();state.month=d.getMonth();state.date=date||dayKey(d);state.news=[];state.message='載入月份新聞…';render();try{await load({monthOnly:true});}catch(e){if(version===calendarSwitchVersion){state.message=e.message||'月份新聞載入失敗';render();}return;}if(version===calendarSwitchVersion){state.message='';render();}}

function reactionPanel(news){const result=studyEvent(news,marketPrices[news.company_code]||[]),pct=v=>v==null?'—':`${v>=0?'+':''}${v.toFixed(2)}%`;if(!result)return `<small>股價反應：${esc(priceMessage[news.company_code]||'等待股價資料與前一交易日基準')}</small>`;return `<details class="reaction"><summary>${esc(result.category)} · 股價反應（事件交易日 ${result.date}）</summary><p>${esc(result.alignment)}。基準：${result.baseline} 收盤 ${result.baselineClose.toFixed(2)}；前 5 日 ${pct(result.before5)}</p><table><thead><tr><th>事件日起</th><th>截止日期</th><th>個股</th><th>大盤</th><th>相對差（百分點）</th></tr></thead><tbody>${result.returns.map(r=>`<tr><td>第 ${r.days} 交易日</td><td>${r.date||'等待資料'}</td><td>${pct(r.stock)}</td><td>${pct(r.market)}</td><td>${r.excess==null?'等待資料':r.excess.toFixed(2)}</td></tr>`).join('')}</tbody></table><small>第 1 交易日包含事件交易日本身；報酬＝截止日收盤 ÷ 基準收盤 − 1。同一檔同日盤中與盤後新聞的基準不同，因此數值可能不同。未還原股價，除權息會影響數值；相對差為個股減加權指數報酬，並非因果推論。同日可能有其他事件。</small></details>`;}
let podcastQueueLimit=30,podcastQueueOpen=false;
function podcastQueuePanel(){const auto=podcastAutoState(),records=resultRecords(state.user?.id||'guest',true),skipped=new Set(auto.skipped),rows=podcast.episodes.map(e=>{const id='podcast:'+e.id,r=records.find(x=>x.id===id),done=!!(r?.text&&r?.answer&&!r.partial&&r.state==='complete');return {e,id,r,done,status:skipped.has(id)?'已略過':auto.currentId===id?'處理中':done?'已完成':r?.state==='interrupted'?'失敗／待續做':r?.partial?'部分完成':auto.enabled?'等待中':'尚未排入'};}),groups=Map.groupBy(rows,row=>row.e.channel_id||row.e.channel_name||'未分類節目');return `<div class="modal-backdrop"><section id="podcast-queue-dialog" class="summary-dialog ai-dialog" role="dialog" aria-modal="true" aria-labelledby="podcast-queue-title"><div style="position:sticky;top:0;background:white;z-index:1;padding-bottom:12px"><div class="modal-heading"><h2 id="podcast-queue-title">Podcast 處理進度</h2><button id="close-podcast-queue" aria-label="關閉處理進度">×</button></div><p role="status">${esc(auto.message||'尚未啟用自動處理')}</p><p>完成 ${rows.filter(r=>r.done).length}／${rows.length} 集 · 待處理 ${rows.filter(r=>!r.done&&!skipped.has(r.id)&&r.id!==auto.currentId).length} 集 · 略過 ${rows.filter(r=>skipped.has(r.id)).length} 集</p>${auto.currentProgress?`<p>${esc(auto.currentProgress)}</p>`:''}<small>逐集選擇是否轉錄；選擇記錄於此裝置。關閉此視窗仍繼續處理，網站分頁需保持開啟。</small></div>${[...groups].map(([key,list])=>`<section class="podcast-queue-group"><h3>${esc(list[0].e.channel_name||podcastChannels().find(c=>c.id===key)?.title||'未分類節目')} · ${list.length} 集</h3><ol>${list.slice(0,podcastQueueLimit).map(({e,id,r,done,status})=>`<li><strong>${esc(e.date)} · ${esc(e.title)}</strong><p role="status">${esc(status)}${r?.progress&&status==='失敗／待續做'?' · '+esc(r.progress):''}</p><label class="ai-check"><input type="checkbox" data-podcast-include="${esc(id)}" ${skipped.has(id)?'':'checked'} ${done?'disabled':''}>${done?'已完成':auto.currentId===id?'轉錄中（取消勾選可停止並略過）':'轉錄並產生 AI 總結'}</label>${r?.answer?`<button data-podcast-result="${esc(id)}">查看本集 AI 總結</button>`:''}</li>`).join('')}</ol>${list.length>podcastQueueLimit?'<button data-podcast-queue-more>顯示更多集數</button>':''}</section>`).join('')||'<p>尚無已匯入集數。</p>'}</section></div>`;}

function mentionedPodcastCard(episode){const matches=(podcastMentionDates.get(episode.date)||[]).filter(({record})=>record.episode?.id===episode.id||record.id==='podcast:'+episode.id||record.title===episode.title),stocks=[...new Map(matches.flatMap(r=>r.stocks).map(c=>[c.code,c])).values()];const badges=stocks.map(c=>`<button data-podcast-episode="${esc(episode.id)}" data-mention-code="${esc(c.code)}">★ 提及 ${esc(c.code)} ${esc(c.name)} · ${esc(c.status)}</button>`).join('');const result=resultRecords(state.user?.id||'guest',true).find(r=>r.id==='podcast:'+episode.id);const summary=result?.answer?`<button data-podcast-result="${esc(result.id)}">查看本集 AI 總結${result.partial?'（部分）':''}</button>`:'';return podcastCard(episode).replace('<div class="stock-actions">',`<div class="stock-actions">${summary}${badges}`);}
function selectedPodcastDates(){if(!state.selected||!podcast.enabled)return '';const dates=[...podcastMentionDates.keys()].sort().reverse(),company=state.companies.find(c=>c.code===state.selected);return `<section class="podcast-watch-mentions"><h3>★ ${esc(company?.name||state.selected)} 出現的 Podcast</h3><small>依已取得的逐字稿／AI 整理比對，未轉錄集數尚無法確認是否提及。</small><div class="podcast-date-links">${dates.map(date=>`<button data-podcast-date="${esc(date)}">${esc(date)} · ${podcastMentionDates.get(date).length} 集</button>`).join('')||'<p>目前已取得的內容中尚無匹配；可先取得該集逐字稿或檢查頻道／來賓篩選。</p>'}</div></section>`;}
function podcastMentionPanel(date){const rows=podcastMentionDates.get(date)||[];return rows.length?`<section class="podcast-watch-mentions"><h3>★ Podcast 提及追蹤股</h3><small>先以逐字稿初步比對，有 AI 結果後對齊總結；${state.selected?'目前選定個股':'目前追蹤清單'}。展開查看原稿；已完成總結可點股名查看標註。</small>${rows.map(({record,stocks})=>`<article><strong>${esc(record.title)}</strong><small>${esc(date)}${record.partial?' · 部分逐字稿':''}</small><div class="stock-actions">${stocks.map(c=>`<button ${record.answer&&!record.legacy?`data-podcast-result="${esc(record.id)}"`:`data-podcast-episode="${esc(record.episode?.id||record.id.replace(/^podcast:/,''))}"`} data-mention-code="${esc(c.code)}">★ ${esc(c.code)} ${esc(c.name)}</button>`).join('')}</div>${stocks.map(c=>`<details><summary>${esc(c.name)} 的提及段落與原稿 · ${esc(c.status)}</summary>${c.passages.map(p=>`<p class="podcast-mentioned-passage">${esc(p)}</p>`).join('')}<small>逐字稿提及片段（保留原稿時間；無時間則不推算）</small>${c.evidence.map(e=>`<blockquote><small>${esc(e.time||'原稿未提供時間')}</small><p>${esc(e.text)}</p></blockquote>`).join('')}</details>`).join('')}</article>`).join('')}</section>`:'';}
function dayWindow(rows,podcasts){return `<div class="modal-backdrop"><section class="summary-dialog day-dialog" id="day-dialog" role="dialog" aria-modal="true" aria-labelledby="day-dialog-title"><div class="modal-heading"><div><h2 id="day-dialog-title">${esc(state.date)} · ${esc(state.selected?(state.previewCompany||state.companies.find(c=>c.code===state.selected))?.name:'全部追蹤公司')}</h2><small>${rows.length} 則新聞 · ${podcasts.length} 集 Podcast</small></div><button id="close-day" aria-label="關閉當日資訊">×</button></div><div class="stock-actions"><button data-day-shift="-1">‹ 上一天</button><button data-day-shift="1">下一天 ›</button></div><div class="summary"><strong>當日新聞摘要</strong><p>${esc(summarize(rows))}</p><small>未選擇公司時，以下內容包含全部追蹤公司的新聞。</small><button id="day-ai-daily" ${rows.length?'':'disabled'}>生成當日 AI 總結</button></div><h3>新聞（${rows.length}）</h3><div class="articles">${rows.map((r,i)=>`<article><div class="meta"><span>${esc(r.company_code)} ${esc(state.companies.find(c=>c.code===r.company_code)?.name||'')}</span><span>${esc(r.source)} · ${esc(new Date(r.published_at).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit'}))}</span></div><a href="${esc(safeURL(r.article_url||r.url))}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a><div><button data-day-local-ai="${i}">個人 AI 摘要</button></div></article>`).join('')||'<p class="empty">當日沒有新聞。</p>'}</div>${podcastMentionPanel(state.date)}<h3>Podcast（${podcasts.length}）</h3><div class="articles">${podcasts.map(mentionedPodcastCard).join('')||'<p class="empty">當日沒有已匯入的 Podcast。</p>'}</div></section></div>`;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
