async function run(fn){if(state.busy)return;state.busy=true;state.message='';render();try{await fn();}catch(e){state.message=e.message||'操作失敗，請稍後重試。';}finally{state.busy=false;render();}}
async function load({monthOnly=false}={}){if(!state.user)return;const version=++monthLoadVersion,owner=state.user.id;if(state.previewCompany&&monthOnly)return;if(!monthOnly)monthCache.clear();const cells=monthCells(state.year,state.month),key=`${state.user.id}:${cells[0].key}:${cells.at(-1).key}`;const cached=monthOnly?monthCache.get(key):undefined;if(cached!==undefined){state.news=cached;return;}const getNews=async()=>{const news=[];let offset=0;while(true){if(version!==monthLoadVersion||owner!==state.user?.id)return [];const result=await api(`/news?from=${cells[0].key}&to=${cells.at(-1).key}&offset=${offset}`);news.push(...result.news);if((result.serverCount??result.news.length)<500)break;offset+=500;}return curateNews(news);};const [news,watchlist]=await Promise.all([getNews(),monthOnly?Promise.resolve(null):api('/watchlists')]);if(version!==monthLoadVersion||owner!==state.user?.id)return;if(watchlist)state.companies=watchlist.companies;state.news=news.filter(n=>{const c=state.companies.find(c=>c.code===n.company_code);return c&&companyMention(n.title,c,c.conflicting_names||[]);});monthCache.set(key,state.news);if(state.selected)void loadPrices(state.selected);else if(!monthOnly)void loadBackgroundPrices();}

async function preview(code){const result=await api('/preview?code='+encodeURIComponent(code));state.previewCompany=result.company;state.preview=curateNews(result.news);state.selected=code;state.matches=[];const d=new Date();state.year=d.getFullYear();state.month=d.getMonth();state.date=state.preview[0]?.news_date||dayKey(d);state.message=`近期新聞 ${state.preview.length} 則（來源回傳範圍），尚未保存到資料庫。`;}
async function search(){if(!state.user)throw Error('請先使用 Google 登入。');const tracked=state.companies.find(c=>c.code===state.query||c.name===state.query||c.full_name===state.query);if(tracked){state.preview=[];state.previewCompany=null;state.selected=tracked.code;state.matches=[];await load();const saved=state.companies.find(c=>c.code===tracked.code);state.message=`已追蹤公司：顯示資料庫新聞。本月符合三家來源與去重條件 ${state.news.filter(n=>n.company_code===tracked.code).length} 則；DB 共保存 ${saved?.news_count??'待確認'} 則（含其他月份及舊來源）。`;return;}state.matches=(await api('/companies?q='+encodeURIComponent(state.query))).companies;const exact=state.matches.find(c=>c.code===state.query||c.name===state.query||c.full_name===state.query);if(exact){state.preview=[];state.previewCompany=null;state.message=`找到 ${exact.code} ${exact.name}，可直接追蹤，或先預覽新聞。`;return;}state.message=state.matches.length?'請選擇公司追蹤，或先預覽新聞。':'找不到公司，請先確認已同步公司名錄。';}
async function add(code){
 if(!state.user)throw Error('請先使用 Google 登入。');
 await api('/watchlists',{body:{code}});
 const company=state.matches.find(c=>c.code===code)||state.previewCompany;
 if(!state.companies.some(c=>c.code===code))state.companies.push(company?.code===code?{...company,news_count:0}:{code,name:code,news_count:0});
 state.preview=[];state.previewCompany=null;state.selected=code;state.matches=[];
 state.message=`已追蹤 ${code}，追蹤清單已保存，正在更新新聞…`;render();
 try{await collect(code);state.message=`已追蹤 ${code}，追蹤清單已保存。${state.message}`;}
 catch(e){state.message=`已追蹤 ${code}，追蹤清單已保存；新聞更新未完成：${e.message||'請稍後按「立即更新新聞」重試。'}`;}
}
async function collect(code){for(const stock of code?[code]:state.companies.map(c=>c.code)){state.message=syncEnabled()?`${stock} 新聞更新工作已排入，等待 GitHub Actions…`:`${stock} 正在讀取新聞並保存至此裝置…`;render();try{await jobRequest('/collect',{code:stock},first=>{state.message=first.dispatched===false?`${stock} 已排入任務，但 GitHub Actions 未啟動；請手動執行 Update company news，mode 選 queued，並檢查 Worker 的 GITHUB_DISPATCH_TOKEN。`:`${stock} 收集任務已建立，等待處理…`;render();});}finally{await load();render();}}state.message=syncEnabled()?'更新已處理；若工作仍排隊，請稍後重新整理。':'新聞已更新並保存至此裝置。';}
