render();const initialPodcasts=loadPodcasts();if(configured)run(async()=>{state.user=await restore();render();if(state.user){await initialPodcasts;const migrationError=await migrateLocalPodcastChannels();Object.assign(podcast,podcastPreferences());await loadPodcasts();if(migrationError){podcast.error=migrationError;render();}await Promise.all([load(),loadRanking()]);}});

function summaryWindow(rows){const groups=Object.groupBy(rows,n=>n.news_date);return `<div class="modal-backdrop"><section class="summary-dialog" id="summary-dialog" role="dialog" aria-modal="true" aria-labelledby="summary-title"><div class="modal-heading"><div><h2 id="summary-title">新聞內文摘要 · ${state.year} 年 ${state.month+1} 月</h2><small>使用上方已設定的個人 AI，先讀取來源內文再生成摘要</small></div><button id="close-summary" aria-label="關閉摘要視窗">×</button></div><div class="stock-actions"><button id="summarize-all" ${!rows.length||!state.user?'disabled':''}>生成本月份多篇新聞總結</button><button id="summary-ai-settings">查看目前 AI 設定</button></div><div class="date-news">${Object.keys(groups).sort().reverse().map(date=>`<section><h3>${esc(date)} · ${groups[date].length} 則</h3><button ${state.user?'':'disabled'} data-ai-day="${esc(date)}">生成當日 AI 總結</button><ul>${groups[date].map(n=>`<li><div class="meta">${esc(n.company_code)} · ${esc(n.source)}</div><a href="${esc(safeURL(n.article_url||n.url))}" target="_blank" rel="noopener noreferrer">${esc(n.title)}</a>${n.article_summary?`<span class="summary-label">既有${n.summary_method==='ai'?' AI 摘要':'內文摘錄'}</span><div class="article-summary markdown-preview markdown-body">${renderMarkdown(n.article_summary)}</div>`:''}<button ${state.user?'':'disabled'} data-local-ai="${esc(String((state.previewCompany?state.preview:state.news).filter(n=>!state.selected||n.company_code===state.selected).indexOf(n)))}">讀取內文並生成 AI 摘要</button></li>`).join('')}</ul></section>`).join('')||'<p class="empty">此月份尚無新聞。</p>'}</div></section></div>`;}

function bindHoldings(){const detail=holdingsDetail,close=()=>{holdingsDetail=null;render();app.querySelector('#open-holdings')?.focus();};app.querySelector('#close-holdings').onclick=close;app.querySelector('#holdings-broker').onchange=e=>{detail.broker=e.target.value;detail.pending=null;detail.error='';detail.message='';render();refreshHoldingsQuotes();};app.querySelector('#holdings-unit').onchange=e=>detail.unit=e.target.value;app.querySelector('#holdings-text').oninput=e=>detail.text=e.target.value;app.querySelector('#holdings-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('檔案上限 1 MB');const encoding=app.querySelector('#holdings-encoding').value,text=new TextDecoder(encoding,{fatal:true}).decode(await file.arrayBuffer());if(holdingsDetail===detail){detail.text=text;detail.error='';render();}}catch(e){if(holdingsDetail===detail){detail.error=e.message==='The encoded data was not valid for encoding utf-8'?'編碼無法辨認，請切換 Big5 再選檔':e.message;render();}}};app.querySelector('#holdings-import').onsubmit=e=>{e.preventDefault();try{detail.pending=parseHoldings(detail.text,detail.unit);detail.error='';detail.message='請確認股數與平均成本，再按確認保存。';}catch(e){detail.error=e.message;detail.pending=null;}render();};app.querySelector('#confirm-holdings')?.addEventListener('click',()=>{try{const records={...detail.records,[detail.broker]:{updatedAt:new Date().toISOString(),rows:detail.pending}};saveHoldings(state.user.id,records);detail.records=records;detail.pending=null;detail.message='庫存已保存於此裝置。';render();refreshHoldingsQuotes();}catch(e){detail.error='此裝置無法保存庫存，請檢查瀏覽器儲存設定。';render();}});app.querySelector('#cancel-holdings-import')?.addEventListener('click',()=>{detail.pending=null;render();});app.querySelector('#clear-holdings').onclick=()=>{if(!confirm('清除此裝置這家券商的庫存明細？'))return;const records={...detail.records};delete records[detail.broker];try{saveHoldings(state.user.id,records);detail.records=records;detail.quotes={};detail.pending=null;render();}catch(e){detail.error='無法清除，請檢查裝置儲存設定。';render();}};app.querySelector('#refresh-holdings-quotes').onclick=refreshHoldingsQuotes;app.querySelectorAll('[data-holding-track]').forEach(b=>b.onclick=()=>run(async()=>{try{await add(b.dataset.holdingTrack);}catch(e){if(holdingsDetail===detail){detail.error=e.message;render();}throw e;}}));app.querySelectorAll('[data-holding-chart]').forEach(b=>b.onclick=()=>{close();openRankingStock(b.dataset.holdingChart);});app.querySelector('#holdings-dialog').onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const nodes=[...e.currentTarget.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};}

