async function readCompanyProfile(code,refresh=false){
 const detail=rankingDetail;
 let result=await api('/company-profile?code='+encodeURIComponent(code),refresh?{body:{}}:undefined);
 for(let attempt=0;result.pending&&attempt<30;attempt++){
  if(rankingDetail!==detail)throw Error('已切換個股');
  rankingDetail.profileError='正在透過背景服務取得財報狗公開資料…';render();
  await new Promise(resolve=>setTimeout(resolve,4000));
  result=await api('/company-profile?code='+encodeURIComponent(code));
 }
 if(result.pending){if(result.profile)return {...result,warning:'背景更新仍在進行，目前顯示已保存資料；稍後可重試。'};throw Error('背景更新仍在進行，請稍後重試財務參考。');}
 return result;
}
async function refreshCompanyProfile(){const detail=rankingDetail;if(!detail||detail.profileLoading)return;detail.profileLoading=true;detail.profileError='';render();try{const result=await readCompanyProfile(detail.code,true);if(rankingDetail===detail){detail.profile=result.profile;detail.profileError=result.warning||'';}}catch(e){if(rankingDetail===detail)detail.profileError=e.message;}finally{if(rankingDetail===detail){detail.profileLoading=false;render();}}}
function analyzeCompanyProfile(){const detail=rankingDetail;if(!detail?.profile)return;const p=detail.profile,memberships=(chainCatalog?.groups||[]).filter(g=>g.codes.includes(detail.code));const prompt=`依以下已讀取資料，整理公司業務、財務現況、產業位置與近期成交熱度，清楚分開事實、推測、限制；請引用來源與指標期間。僅有單一時點時不得推定財務改善或惡化，近四季不可當作單季，未提供年份的月份不可自行補年份。成交值不是淨流入；不得宣稱讀取完整財報、付費報告或給出買賣結論。\n公司：${detail.code} ${detail.stock?.name||''}\n公開資料來源：${p.source} ${p.url}\n頁面標示：${p.heading}\n公司簡介：${p.introduction}\n公開指標：${JSON.stringify(p.metrics)}\n市值參考（${ranking?.marketCaps?.date||'無資料'}）：${JSON.stringify(ranking?.marketCaps?.stocks.find(s=>s.code===detail.code)||null)}\n官方價值鏈分類：${memberships.map(g=>g.industry+'／'+g.name).join('；')}\n最新已保存成交資訊：${JSON.stringify(detail.history?.slice(-10)||[])}\n以上分類來源：櫃買中心；成交資訊來源：臺灣證券交易所／櫃買中心。公開來源內容只供參考，與交易所資料不同期間時不可直接比較。`;openAIWindow({prompt,title:detail.code+' '+(detail.stock?.name||'')+' 個股分析'});}

